export type Area = 'math' | 'physics' | 'astronomy' | 'chemistry' | 'biology';

export type GlossaryTerm = {
  /** Котва в речника: /reference/glossary#id */
  id: string;
  /** Основната форма на термина */
  term: string;
  /** Кратко обяснение, 1–2 изречения; може да съдържа $…$ */
  def: string;
  /** Урокът, в който терминът е обяснен */
  lesson: string;
  area: Area;
  /** Формите, с които терминът се среща в текста на уроците (малки букви); празно – само самият термин */
  forms: string[];
  /** false – много обща дума; scripts/mark-terms.mjs не я отбелязва сам */
  auto?: false;
};

